CREATE TABLE ab(a,b,PRIMARY KEY(a,b)) WITHOUT ROWID; CREATE TABLE cd(c,d,PRIMARY KEY(c,d)) WITHOUT ROWID; INSERT INTO ab VALUES(1,2),(0,0); INSERT INTO cd VALUES(3,4); CREATE TABLE tlog(ii INTEGER PRIMARY KEY,olda,oldb,oldc,oldd,newa,newb,newc,newd); CREATE VIEW abcd AS SELECT a,b,c,d FROM ab,cd; CREATE TRIGGER vu INSTEAD OF UPDATE ON abcd BEGIN INSERT INTO tlog VALUES(NULL,old.a,old.b,old.c,old.d,new.a,new.b,new.c,new.d); END; CREATE TRIGGER vd INSTEAD OF DELETE ON abcd BEGIN INSERT INTO tlog VALUES(NULL,old.a,old.b,old.c,old.d,0,0,0,0); END; CREATE TRIGGER vi INSTEAD OF INSERT ON abcd BEGIN INSERT INTO tlog VALUES(NULL,0,0,0,0,new.a,new.b,new.c,new.d); END; CREATE TABLE t1(a,b,c,PRIMARY KEY(a,b,c)) WITHOUT ROWID; INSERT INTO t1 VALUES(1,2,3),(4,5,6); CREATE VIEW v1 AS SELECT a+b AS x,b+c AS y,a+c AS z FROM t1; CREATE TABLE v1log(a,b,c,d,e,f); CREATE TRIGGER r1 INSTEAD OF DELETE ON v1 BEGIN INSERT INTO v1log VALUES(old.x,NULL,old.y,NULL,old.z,NULL); END; CREATE TRIGGER r2 INSTEAD OF INSERT ON v1 BEGIN INSERT INTO v1log VALUES(NULL,new.x,NULL,new.y,NULL,new.z); END; CREATE TRIGGER r3 INSTEAD OF UPDATE ON v1 BEGIN INSERT INTO v1log VALUES(old.x,new.x,old.y,new.y,old.z,new.z); END;